-- Dumping data for table webbansach.book: ~20 rows (approximately)
INSERT INTO `book` (`book_id`, `book_name`, `descripstion`, `list_price`, `price`, `quantity`) VALUES
	(1, 'Đắc Nhân Tâm', 'Đắc Nhân Tâm của Dale Carnegie là quyển sách duy nhất về thể loại self-help liên tục đứng đầu danh mục sách bán chạy nhất (best-selling Books) do báo The New York Times bình chọn suốt 10 năm liền. Được xuất bản năm 1936, với số lượng bán ra hơn 15 triệu bản, tính đến nay, sách đã được dịch ra ở hầu hết các ngôn ngữ, trong đó có cả Việt Nam, và đã nhận được sự đón tiếp nhiệt tình của đọc giả ở hầu hết các quốc gia.', 108000, 90000, 62),
	(2, 'Sách Nghe Hiểu Tiếng Nhật N4', 'Giúp cho bạn học tiếng Nhật trở nên dễ dàng hơn.', 65000, 60000, 223),
	(3, 'Thỏ Bảy Màu', 'Thỏ Bảy Màu là một nhân vật hư cấu chẳng còn xa lạ gì với anh em dùng mạng xã hội với slogan "Nghe lời Thỏ, kiếp này coi như bỏ!". Thỏ Bảy Màu đơn giản chỉ là một con thỏ trắng với sự dở hơi, ngang ngược nhưng đáng yêu vô cùng tận. Nó luôn nghĩ rằng mình không có cuộc sống và không có bạn bè. Tuy nhiên, Thỏ lại chẳng bao giờ thấy cô đơn vì đến cô đơn cũng bỏ nó mà đi.', 99000, 84000, 54),
	(4, 'Đám Trẻ Ở Đại Dương Đen', 'Đám trẻ ở đại dương đen là lời độc thoại và đối thoại của những đứa trẻ ở đại dương đen, nơi từng lớp sóng của nỗi buồn và tuyệt vọng không ngừng cuộn trào, lúc âm ỉ, khi dữ dội. Những đứa trẻ ấy phải vật lộn trong những góc tối tâm lý, với sự u uất đè nén từ tổn thương khi không được sinh ra trong một gia đình toàn vẹn, ấm êm, khi phải mang trên đôi vai non dại những gánh nặng không tưởng.', 99000, 75000, 50),
	(5, 'Đại Gia Gatsby', 'Một tiểu thuyết viết bởi tác giả người Mỹ F. Scott Fitzgerald.', 20000, 18999, 100),
	(6, 'Giết Con Chim Nhại', 'Một tiểu thuyết của Harper Lee được xuất bản vào năm 1960, là một tác phẩm nổi tiếng trong các trường học tại Mỹ.', 14000, 15000, 50),
	(7, 'Harry Potter Và Hòn Đá Phù Thuỷ', 'Khi một lá thư được gởi đến cho cậu bé Harry Potter bình thường và bất hạnh, cậu khám phá ra một bí mật đã được che giấu suốt cả một thập kỉ. Cha mẹ cậu chính là phù thủy và cả hai đã bị lời nguyền của Chúa tể Hắc ám giết hại khi Harry mới chỉ là một đứa trẻ, và bằng cách nào đó, cậu đã giữ được mạng sống của mình. Thoát khỏi những người giám hộ Muggle không thể chịu đựng nổi để nhập học vào trường Hogwarts, một trường đào tạo phù thủy với những bóng ma và phép thuật, Harry tình cờ dấn thân vào một cuộc phiêu lưu đầy gai góc khi cậu phát hiện ra một con chó ba đầu đang canh giữ một căn phòng trên tầng ba. Rồi Harry nghe nói đến một viên đá bị mất tích sở hữu những sức mạnh lạ kì, rất quí giá, vô cùng nguy hiểm, mà cũng có thể là mang cả hai đặc điểm trên.', 25000, 19000, 20),
	(8, 'Kiêu Hãnh và Định Kiến', 'Một tiểu thuyết lãng mạn của Jane Austen. Nó đề cập đến các vấn đề về đẳng cấp, hôn nhân và đạo đức.', 51000, 87800, 250),
	(9, 'Vương Quốc Lúa Mạch Đen - Lược Sử Ẩm Thực Nga', 'Darra Goldstein, một chuyên gia hàng đầu về văn hóa và ẩm thực Nga, xuất thân từ một gia đình đã rời bỏ Nga vào đầu thế kỷ 20, điều này đã thôi thúc bà tìm hiểu về vùng đất tổ tiên và sau nhiều trải nghiệm, điều cuốn hút bà hơn cả là nền văn hóa ẩm thực của đất nước này. Bắt đầu từ những món ăn xa xỉ quyến rũ được mô tả trong các tác phẩm văn học Nga cho đến thực tế thiếu thốn và cách người Nga biến khó khăn thành sáng tạo trong nấu nướng mà bà phải đối mặt khi đến Nga vào thời kỳ Liên Xô, Goldstein nhận ra rằng ẩm thực không chỉ là việc nuôi sống con người mà còn là biểu tượng cho sức mạnh tinh thần, sự kiên trì và bản sắc dân tộc. VƯƠNG QUỐC LÚA MẠCH ĐEN chính là tác phẩm thể hiện niềm đam mê của Goldstein trong việc truyền tải câu chuyện văn hóa sâu sắc thông qua ẩm thực, cũng như tôn vinh những giá trị truyền thống đã tồn tại và phát triển qua nhiều thời kỳ lịch sử đầy biến động của Nga.', 12000, 13000, 120),
	(10, 'Kiểm Soát Chi Phí Mua Hàng Và Quản Lí Nhà Cung Cấp (2022)', 'Trạng thái lí tưởng trong vận hành doanh nghiệp là gì? “Mua vào rẻ, bán ra đắt, các khâu trung gian không lãng phí thất thoát”, dường như câu nói này rất đơn giản nhưng lại diễn tả một cách trực quan những thách thức rất hiện thực về việc doanh nghiệp khi quản lí cần đạt hiệu ích như thế nào ở các khâu mua hàng, tiêu thụ và vận hành.', 18000, 20000, 80),
	(11, '“Chậm” Để Trải Nghiệm, “Chậm” Để Tận Hưởng, “Chậm” Để Trưởng Thành', 'Những lo lắng hay hy vọng về cuộc đời có lẽ ẩn hiện trong những nhân viên công sở tan làm, ngồi ở một con hẻm nhỏ ăn một bát cháo thịt băm; cũng có thể là tấm hình thần tượng được treo trên tường trong những phòng kí túc xá cũ; hay cũng có thể là một ngày lạc trong rừng sâu ngồi trò chuyện với vị hòa thượng già.', 11000, 32000, 10),
	(12, 'Xin Lỗi Con, Cha Mẹ Cũng Cần Được Chữa Lành', 'Xin Lỗi Con, Cha Mẹ Cũng Cần Được Chữa Lành', 27000, 22000, 50),
	(13, 'Cuộc Phiêu Lưu Của Hổ', 'Trở về Oregon, Kelsey cố quay lại cuộc sống thường nhật và gạt đi cảm xúc cô dành cho Ren. Mùa hè tuổi mười tám của Kelsey Hayes thật điên rồ. Sẽ chẳng có ai tin câu chuyện mà cô đã trải qua.', 22300, 11200, 180),
	(14, 'Búp Sen Xanh (Tái Bản 2020)', 'Có thể xếp “Búp Sen Xanh” vào nhóm tác phẩm văn học dành cho thiếu nhi và là tác phẩm nổi tiếng nhất viết về chủ tịch Hồ Chí Minh trong suốt thời thơ ấu cho đến khi rời Việt Nam sang Pháp.', 32000, 15000, 200),
	(15, '7 Thói Quen Hiệu Quả - The 7 Habits Of Highly Effective People - Bìa Cứng (Tái Bản 2022)', 'Đây là một cuốn sách sẽ “tìm đến bạn” vào thời điểm thích hợp. Khi đã sẵn sàng mở rộng tầm nhận thức của mình, bạn sẽ thấy các cánh cửa được mở ra. 7 thói quen đánh thức tiềm năng sáng tạo đại diện cho một cánh cửa như vậy.Cuốn sách này dành cho bất cứ ai muốn tiếp cận được nhiều sức sáng tạo và trạng thái dòng chảy hơn trong cuộc sống thường ngày. Có lẽ bạn tin rằng mình gần như không có chút tài năng nghệ thuật nào. Có lẽ trong quá khứ, cha mẹ hay giáo viên đã nói rằng bạn thiếu khả năng sáng tạo. Hoặc có thể bạn nhận thấy mình có khả năng sáng tạo bẩm sinh, và bạn muốn phát triển những thói quen, những kĩ năng đó tốt hơn nữa... Dù bạn đang ở bất cứ đâu trên bàn cân của sự sáng tạo, cuốn sách này cũng sẽ giúp bạn thay đổi và phát triển sức sáng tạo ở mức độ sâu sắc hơn. Trên hành trình này, bạn sẽ học được những thói quen mà những người giàu sức sáng tạo đã trau dồi – những thói quen sẽ cho phép bạn tận dụng toàn bộ tiềm lực sáng tạo của mình. Và rồi bạn sẽ sớm nhận thấy tác động tích cực của nó trong đời sống hằng ngày, bao gồm sự nghiệp, sức khỏe và các mối quan hệ của bạn.', 75000, 85000, 62),
	(16, 'Muôn Kiếp Nhân Sinh - Many Times, Many Lives', 'Nối tiếp câu chuyện và tinh thần của tập 1 và tập 2, Muôn Kiếp Nhân Sinh – tập 3 tiếp tục đưa bạn đọc đi qua hành trình thức tỉnh tâm linh của nhân vật chính Thomas. Không chỉ là hồi tiếp theo trong chuyến phiêu lưu của linh hồn, tập mới nhất và cũng là tập cuối cùng của bộ sách sẽ bàn luận sâu hơn về hiện tại và tương lai của nhân loại, đồng thời nhẹ nhàng khép lại câu chuyện tiền kiếp nhiều trăn trở, nhiều bài học của Thomas và giải đáp những câu hỏi còn bỏ ngỏ từ hai tập trước.', 128000, 89600, 15),
	(17, 'Tư Duy Ngược', 'Chúng ta thực sự có hạnh phúc không? Chúng ta có đang sống cuộc đời mình không? Chúng ta có dám dũng cảm chiến thắng mọi khuôn mẫu, định kiến, đi ngược đám đông để khẳng định bản sắc riêng của mình không? Có bao giờ bạn tự hỏi như thế, rồi có câu trả lời cho chính mình?', 139000, 69500, 65),
	(18, 'Nhà Lãnh Đạo Đáng Tin Cậy', 'Nhà lãnh đạo đáng tin cậy là quyển sách về sự tiên liệu, một quyển sách về tương lai, nơi khả năng lãnh đạo được xác định bởi độ đáng tin cậy. Một quyển sách về năng lực, tính chính trực và lòng nhân từ. Một quyển sách về việc phát triển những thói quen lãnh đạo mới sao cho phù hợp với một thế giới mới – một thế giới của sự minh bạch.', 190000, 85500, 54),
	(19, 'Những Trí Tuệ Vĩ Đại - Hawking: Người Đàn Ông Phi Thường, Một Thiên Tài Vĩ Đại Và Cha Đẻ Của Thuyết Vạn Vật', 'Stephen Hawking qua đời vào tháng 3 năm 2018 đã khép lại một trong những câu chuyện về cuộc đời khoa học truyền cảm hứng và đáng nhớ nhất mọi thời đại. Có lẽ là nhà vũ trụ học người Anh vĩ đại nhất kể từ thời của Newton và là nhà khoa học được săn đón nhất thời hiện đại, câu chuyện về cuộc đời của Hawking đã vượt ra ngoài lĩnh vực học thuật.', 229000, 139000, 95),
	(20, 'Hôn Nhân Của Cha Mẹ Dạy Con Cái Điều Gì? - Trồng Một Người Cha Gieo Lên Người Mẹ Và Đổ Đầy Hạnh Phúc Vào Những Đứa Trẻ', 'Hôn nhân và Nuôi dạy con cái có mối liên quan trực tiếp và tác động qua lại với nhau vô cùng mạnh. Một cuộc Hôn nhân Hạnh Phúc sẽ tạo ra những đứa trẻ Hạnh Phúc. Và ngược lại, chính những đứa trẻ là chất keo gắn kết và nuôi dưỡng Hôn nhân bền vững hơn. Ngay cả khi cuộc Hôn nhân đó không còn lành lặn, nếu người cha, người mẹ vẫn yêu thương con cái, mong muốn điều tốt đẹp nhất cho con thì Ly dị không phải là bi kịch với lũ trẻ.', 78000, 54600, 34);

